import axios from "axios";

const BASE_URL = (
  process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database"
).replace(/\/$/, "");

export const api = {
  
  getCountryList: async (): Promise<any> => {
    try {
      const response = await axios.get(`${BASE_URL}/data/country.json`);
      return response.data;
    } catch (error) {
      console.error("Error fetching country list:", error);
      throw error;
    }
  },

  
  getASNList: async (): Promise<any> => {
    try {
      const response = await axios.get(`${BASE_URL}/data/asn.json`);
      return response.data;
    } catch (error) {
      console.error("Error fetching ASN list:", error);
      throw error;
    }
  },

  
  getCountryData: async (countryCode: string): Promise<any> => {
    try {
      const response = await axios.get(
        `${BASE_URL}/data/country/${countryCode.toUpperCase()}/get.json`,
      );
      return response.data;
    } catch (error) {
      console.error(`Error fetching country data for ${countryCode}:`, error);
      throw error;
    }
  },

  
  getASNData: async (countryCode: string): Promise<any> => {
    try {
      const response = await axios.get(
        `${BASE_URL}/data/asn/${countryCode.toUpperCase()}/get.json`,
      );
      return response.data;
    } catch (error) {
      console.error(`Error fetching ASN data for ${countryCode}:`, error);
      throw error;
    }
  },

  
  getASNById: async (countryCode: string, asn: string): Promise<any> => {
    try {
      const response = await axios.get(
        `${BASE_URL}/data/asn/${countryCode.toUpperCase()}/${asn}/get.json`,
      );
      return response.data;
    } catch (error) {
      console.error(`Error fetching ASN ${asn} for ${countryCode}:`, error);
      throw error;
    }
  },
};
