import { create } from "zustand";
import { CountryData, ASNData, CountryInfo, ASNInfo } from "@/types";

interface DataStore {
  
  countries: CountryInfo[];
  countryData: Record<string, CountryData[]>;
  countriesLoading: boolean;
  countriesError: string | null;

  
  asns: ASNInfo[];
  asnData: Record<string, Record<string, ASNData[]>>;
  asnsLoading: boolean;
  asnsError: string | null;

  
  setCountries: (countries: CountryInfo[]) => void;
  setCountryData: (countryCode: string, data: CountryData[]) => void;
  setASNs: (asns: ASNInfo[]) => void;
  setASNData: (countryCode: string, asn: string, data: ASNData[]) => void;
  setCountriesLoading: (loading: boolean) => void;
  setASNsLoading: (loading: boolean) => void;
  setCountriesError: (error: string | null) => void;
  setASNsError: (error: string | null) => void;

  
  reset: () => void;
}

export const useDataStore = create<DataStore>((set) => ({
  countries: [],
  countryData: {},
  countriesLoading: false,
  countriesError: null,

  asns: [],
  asnData: {},
  asnsLoading: false,
  asnsError: null,

  setCountries: (countries) => set({ countries }),
  setCountryData: (countryCode, data) =>
    set((state) => ({
      countryData: { ...state.countryData, [countryCode]: data },
    })),
  setASNs: (asns) => set({ asns }),
  setASNData: (countryCode, asn, data) =>
    set((state) => ({
      asnData: {
        ...state.asnData,
        [countryCode]: { ...state.asnData[countryCode], [asn]: data },
      },
    })),
  setCountriesLoading: (loading) => set({ countriesLoading: loading }),
  setASNsLoading: (loading) => set({ asnsLoading: loading }),
  setCountriesError: (error) => set({ countriesError: error }),
  setASNsError: (error) => set({ asnsError: error }),
  reset: () =>
    set({
      countries: [],
      countryData: {},
      asns: [],
      asnData: {},
      countriesLoading: false,
      asnsLoading: false,
      countriesError: null,
      asnsError: null,
    }),
}));
