"use client";

import { useEffect, useState } from "react";
import { useDataStore } from "@/stores/data-store";
import { api } from "@/lib/api";
import { CountryData, ASNData, CountryInfo, ASNInfo } from "@/types";


export function useCountries() {
  const {
    countries,
    countriesLoading,
    countriesError,
    setCountries,
    setCountriesLoading,
    setCountriesError,
  } = useDataStore();

  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const fetchCountries = async () => {
      
      if (countries.length > 0) {
        setLoaded(true);
        return;
      }

      setCountriesLoading(true);
      try {
        const result = await api.getCountryList();
        
        const countryList = Array.isArray(result)
          ? result
          : result.countries || [];
        setCountries(countryList);
        setLoaded(true);
      } catch (error) {
        const errorMsg =
          error instanceof Error ? error.message : "Failed to load countries";
        setCountriesError(errorMsg);
        console.error("Error fetching countries:", error);
      } finally {
        setCountriesLoading(false);
      }
    };

    fetchCountries();
  }, [countries.length, setCountries, setCountriesLoading, setCountriesError]);

  return {
    countries,
    loading: countriesLoading,
    error: countriesError,
    loaded,
  };
}


