export function useCountryData(countryCode: string) {
  const {
    countryData,
    setCountryData,
    setCountriesLoading,
    setCountriesError,
  } = useDataStore();

  const [data, setData] = useState<CountryData[]>([]);
  const [loading, setLocalLoading] = useState(true);
  const [error, setLocalError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      if (!countryCode) {
        setLocalLoading(false);
        return;
      }

      const upperCode = countryCode.toUpperCase();

      
      if (countryData[upperCode]) {
        setData(countryData[upperCode]);
        setLocalLoading(false);
        return;
      }

      setLocalLoading(true);
      setCountriesLoading(true);
      setLocalError(null);

      try {
        const result = await api.getCountryData(upperCode);
        
        const countryDataResult = Array.isArray(result) ? result : [];
        setData(countryDataResult);
        setCountryData(upperCode, countryDataResult);
      } catch (error) {
        const errorMsg =
          error instanceof Error
            ? error.message
            : `Failed to load data for ${upperCode}`;
        setLocalError(errorMsg);
        setCountriesError(errorMsg);
        console.error(`Error fetching country data for ${upperCode}:`, error);
      } finally {
        setLocalLoading(false);
        setCountriesLoading(false);
      }
    };

    fetchData();
  }, [
    countryCode,
    countryData,
    setCountryData,
    setCountriesLoading,
    setCountriesError,
  ]);

  return { data, loading, error };
}


export function useASNData(countryCode: string, asn?: string) {
  const { asnData, setASNData, setASNsLoading, setASNsError } = useDataStore();

  const [data, setData] = useState<ASNData[]>([]);
  const [loading, setLocalLoading] = useState(true);
  const [error, setLocalError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      if (!countryCode) {
        setLocalLoading(false);
        return;
      }

      const upperCode = countryCode.toUpperCase();

      if (asn) {
        
        const cacheKey = `asn_${asn}`;
        if (asnData[upperCode]?.[cacheKey]) {
          setData(asnData[upperCode][cacheKey]);
          setLocalLoading(false);
          return;
        }

        setLocalLoading(true);
        setASNsLoading(true);
        setLocalError(null);

        try {
          const result = await api.getASNById(upperCode, asn);
          const asnResult = Array.isArray(result) ? result : [result];
          setData(asnResult);
          setASNData(upperCode, cacheKey, asnResult);
        } catch (error) {
          const errorMsg =
            error instanceof Error
              ? error.message
              : `Failed to load AS${asn} data`;
          setLocalError(errorMsg);
          setASNsError(errorMsg);
          console.error(`Error fetching ASN ${asn} for ${upperCode}:`, error);
        } finally {
          setLocalLoading(false);
          setASNsLoading(false);
        }
      } else {
        
        const cacheKey = "_all";
        if (asnData[upperCode]?.[cacheKey]) {
          setData(asnData[upperCode][cacheKey]);
          setLocalLoading(false);
          return;
        }

        setLocalLoading(true);
        setASNsLoading(true);
        setLocalError(null);

        try {
          const result = await api.getASNData(upperCode);
          const asnResult = Array.isArray(result) ? result : [];
          setData(asnResult);
          setASNData(upperCode, cacheKey, asnResult);
        } catch (error) {
          const errorMsg =
            error instanceof Error
              ? error.message
              : `Failed to load ASN data for ${upperCode}`;
          setLocalError(errorMsg);
          setASNsError(errorMsg);
          console.error(`Error fetching ASN data for ${upperCode}:`, error);
        } finally {
          setLocalLoading(false);
          setASNsLoading(false);
        }
      }
    };

    fetchData();
  }, [countryCode, asn, asnData, setASNData, setASNsLoading, setASNsError]);

  return { data, loading, error };
}


export function useCountryByCode(countryCode: string) {
  const { countries } = useDataStore();
  const [country, setCountry] = useState<CountryInfo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (countries.length > 0 && countryCode) {
      const found = countries.find(
        (c) => c.code.toUpperCase() === countryCode.toUpperCase(),
      );
      setCountry(found || null);
      setLoading(false);
    } else if (countryCode) {
      setLoading(true);
    } else {
      setCountry(null);
      setLoading(false);
    }
  }, [countries, countryCode]);

  return { country, loading };
}


export function useASNByNumber(asnNumber: string) {
  const { asns } = useDataStore();
  const [asn, setAsn] = useState<ASNInfo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (asns.length > 0 && asnNumber) {
      const found = asns.find(
        (a) => a.asn === asnNumber || a.asn === `AS${asnNumber}`,
      );
      setAsn(found || null);
      setLoading(false);
    } else if (asnNumber) {
      setLoading(true);
    } else {
      setAsn(null);
      setLoading(false);
    }
  }, [asns, asnNumber]);

  return { asn, loading };
}
